import gzip,importlib.util,io,re,sys,zipfile
from pathlib import PurePosixPath
spec=importlib.util.spec_from_file_location('vp',r'/Users/yin/code/cryProject/deliverables/support/CACR2026EA16XZ-multi-leakage-platform-20261016/verify_package.py')
vp=importlib.util.module_from_spec(spec);spec.loader.exec_module(vp)
with zipfile.ZipFile(r'/Users/yin/code/cryProject/deliverables/support/CACR2026EA16XZ-multi-leakage-platform-20261016/CACR2026EA16XZ-platform-final64-20261021.zip') as archive:
    names=archive.namelist()
    hits=[]
    scanned=0
    for name in names:
        content=archive.read(name)
        suffix=PurePosixPath(name).suffix.lower()
        if suffix == '.gz':
            # 压缩成员必须**解压后**再扫（包审计也是这么做的）
            try:
                content = gzip.decompress(content)
            except Exception:
                continue
        elif suffix == '.docx':
            # Word 文档是 ZIP：抽内部 XML 文字层再扫（与包审计一致）
            try:
                with zipfile.ZipFile(io.BytesIO(content)) as inner:
                    content = b'\n'.join(inner.read(m) for m in inner.namelist() if m.endswith('.xml'))
            except Exception:
                continue
        elif suffix in vp.BINARY_SUFFIXES:
            try:
                import fitz
                with fitz.open(stream=io.BytesIO(content)) as document:
                    text='\n'.join(document[i].get_text() for i in range(document.page_count))
                content=text.encode('utf-8','ignore')
            except Exception:
                continue
        elif suffix not in vp.TEXT_SUFFIXES:
            continue
        scanned+=1
        for pattern in vp.PRIVATE_PATTERNS:
            if re.search(pattern,content):
                hits.append((name,pattern))
    print('scanned',scanned,'hits',hits[:5])
    sys.exit(1 if hits else 0)
